// Spanish and French conjugation drills. Regular verbs are generated by rule; anything
// irregular comes from the word's `forms` (six-person tables, participle, imperative). A verb the
// rules can't settle (a spelling change, a stem change the data doesn't give) is refused or
// skipped, never guessed. Data format: docs/COURSE_FORMAT.md, "Conjugation drills".

import type { VocabItem } from "./types";

export interface RomanceGenerated {
  answers: string[];
  rule: string;
}

/** Persons drilled, as indexes into a six-person table. Spanish skips vosotros (4). */
export const ES_PERSONS = [0, 1, 2, 3, 5] as const;
export const FR_PERSONS = [0, 1, 2, 3, 4, 5] as const;
export const ES_IMPERATIVES = ["tú", "usted"] as const;
export const FR_IMPERATIVES = ["tu", "nous", "vous"] as const;

export const ES_LABEL = ["yo", "tú", "él/ella/usted", "nosotros", "vosotros", "ellos/ellas/ustedes"];
export const FR_LABEL = ["je", "tu", "il/elle/on", "nous", "vous", "ils/elles"];
const ES_PRONOUNS = [["yo"], ["tú", "tu"], ["él", "ella", "usted", "el"], ["nosotros", "nosotras"], ["vosotros", "vosotras"], ["ellos", "ellas", "ustedes"]];
const FR_PRONOUNS = [["je"], ["tu"], ["il", "elle", "on"], ["nous"], ["vous"], ["ils", "elles"]];

const table = (s: string | undefined): string[] | undefined => {
  if (!s) return undefined;
  const t = s.split(",").map((x) => x.trim());
  return t.length === 6 && t.every(Boolean) ? t : undefined;
};

/** A table cell may give alternatives: "paie/paye". */
const alts = (cell: string) => cell.split("/").map((x) => x.trim()).filter(Boolean);

/** Add "yo ", "Yo " … variants. French je elides before a vowel or h. A cell's alternatives all count. */
function withPronouns(form: string, prons: string[], lang: "es" | "fr"): string[] {
  if (form.includes("/")) return [...new Set(alts(form).flatMap((f) => withPronouns(f, prons, lang)))];
  const out = [form];
  for (const p of prons) {
    const joined = lang === "fr" && p === "je" && /^[aeiouyhâàéèêëîïôûœ]/i.test(form) ? `j'${form}` : `${p} ${form}`;
    out.push(joined, joined[0].toUpperCase() + joined.slice(1));
  }
  return [...new Set(out)];
}

// ---------------------------------------------------------------------------------------------
// Spanish

interface EsVerb {
  term: string;
  cls: "ar" | "er" | "ir";
  reflexive: boolean;
  /** Infinitive without -se. */
  base: string;
  stem: string;
  present?: string[];
  preterite?: string[];
  f: NonNullable<VocabItem["forms"]>;
}

const ES_REFL = ["me", "te", "se", "nos", "os", "se"];
const ES_PRESENT_END = { ar: ["o", "as", "a", "amos", "áis", "an"], er: ["o", "es", "e", "emos", "éis", "en"], ir: ["o", "es", "e", "imos", "ís", "en"] };
const ES_PRETERITE_END = { ar: ["é", "aste", "ó", "amos", "asteis", "aron"], er: ["í", "iste", "ió", "imos", "isteis", "ieron"], ir: ["í", "iste", "ió", "imos", "isteis", "ieron"] };
const HABER = ["he", "has", "ha", "hemos", "habéis", "han"];
/** Common verbs whose present or preterite isn't regular: warn when their data is missing. */
const ES_IRREGULAR = [
  "ser", "estar", "ir", "tener", "venir", "hacer", "poner", "salir", "decir", "dar", "ver", "saber", "poder", "querer", "pensar", "empezar",
  "entender", "cerrar", "preferir", "sentir", "dormir", "morir", "volver", "contar", "costar", "encontrar", "recordar", "almorzar", "jugar",
  "pedir", "repetir", "servir", "seguir", "vestir", "conocer", "traer", "oír", "caer", "conducir", "traducir", "despertar", "acostar",
  "sentar", "probar", "mostrar", "llover", "nevar", "mover", "perder", "querer", "elegir", "reír", "sonreír", "divertir", "comenzar",
];

function esVerb(item: VocabItem): EsVerb | string {
  const term = item.term.trim();
  const cls = item.conj as "ar" | "er" | "ir";
  if (!["ar", "er", "ir"].includes(cls)) return `"${item.conj}" isn't a Spanish verb class (ar, er, ir)`;
  if (!/^[a-záéíóúüñ]+$/.test(term)) return `"${term}" must be a one-word infinitive in lower case`;
  const reflexive = /(ar|er|ir|ír)se$/.test(term);
  const base = reflexive ? term.slice(0, -2) : term;
  const ending = base.slice(-2).replace("í", "i");
  if (ending !== cls) return `"${term}" ends in -${ending}, not -${cls}`;
  const f = item.forms ?? {};
  for (const k of ["present", "preterite", "imperfect"] as const)
    if (f[k] && !table(f[k])) return `forms.${k} needs six comma-separated forms (yo, tú, él, nosotros, vosotros, ellos)`;
  if (f.imperfectStem) return `forms.imperfectStem is for French`;
  const present = table(f.present);
  const preterite = table(f.preterite);
  if (present && reflexive && !present.every((x, i) => x.startsWith(ES_REFL[i] + " ")))
    return `forms.present of a reflexive verb gives the pronouns: "me levanto, te levantas, se levanta, …"`;
  if (f.aux) return `forms.aux is for French`;
  const stem = base.slice(0, -2);
  if (!present) {
    if (/(c|g)[ei]r$/.test(base) || /[^g]uir$/.test(base) || /guir$/.test(base))
      return `"${term}" changes its spelling in the present (conozco, escojo, sigo, construyo…): give forms.present`;
    if (base === "ir" || base.length < 4) return `"${term}" is irregular: give forms.present`;
  }
  return { term, cls, reflexive, base, stem, present, preterite, f };
}

const ES_IMPERFECT_AR = ["aba", "abas", "aba", "ábamos", "abais", "aban"];
const ES_IMPERFECT_ER = ["ía", "ías", "ía", "íamos", "íais", "ían"];
const ES_FUTURE_END = ["é", "ás", "á", "emos", "éis", "án"];
const ES_CONDITIONAL_END = ["ía", "ías", "ía", "íamos", "íais", "ían"];
/** Verbs (and their compounds) whose future stem isn't the infinitive: tendr-, har-, dir-… */
const ES_IRREGULAR_FUTURE = /(tener|poner|salir|venir|poder|saber|haber|caber|querer|hacer|decir|valer)$/;

function esFutureStem(v: EsVerb): string | undefined {
  if (v.f.futureStem) return v.f.futureStem;
  if (ES_IRREGULAR_FUTURE.test(v.base)) return undefined;
  return v.base.replace(/ír$/, "ir");
}

export function esWordProblem(item: VocabItem): string | undefined {
  const v = esVerb(item);
  return typeof v === "string" ? v : undefined;
}

function esPresent(v: EsVerb, i: number): { form: string; given: boolean } {
  if (v.present) return { form: v.present[i], given: true };
  const x = v.stem + ES_PRESENT_END[v.cls][i];
  return { form: v.reflexive ? `${ES_REFL[i]} ${x}` : x, given: false };
}

/** The participle: given, or -ado / -ido (-ído after a, e, o: leído, traído, oído). */
function esParticiple(v: EsVerb): { p: string; given: boolean } {
  if (v.f.participle) return { p: v.f.participle, given: true };
  if (v.cls === "ar") return { p: v.stem + "ado", given: false };
  return { p: v.stem + (/[aeo]$/.test(v.stem) ? "ído" : "ido"), given: false };
}

export function esVerbForm(item: VocabItem, form: string, person: string | number): RomanceGenerated | undefined {
  const v = esVerb(item);
  if (typeof v === "string") return undefined;
  const i = Number(person);
  const label = ES_LABEL[i];
  switch (form) {
    case "present": {
      const { form: x, given } = esPresent(v, i);
      const rule = given
        ? `${v.term} is irregular in the present: ${label} ${x} (${v.present!.filter((_, k) => k !== 4).join(", ")})`
        : `Regular -${v.cls} verb: stem ${v.stem}- + -${ES_PRESENT_END[v.cls][i]}${v.reflexive ? `, with the pronoun ${ES_REFL[i]}` : ""}`;
      return { answers: withPronouns(x, ES_PRONOUNS[i], "es"), rule };
    }
    case "preterite": {
      let x: string;
      let rule: string;
      if (v.preterite) {
        x = v.preterite[i];
        rule = `${v.term} has an irregular or respelled preterite: ${v.preterite.filter((_, k) => k !== 4).join(", ")}`;
      } else {
        if (/(car|gar|zar)$/.test(v.base) || /[aeo](er|ir)$/.test(v.base) || /uir$/.test(v.base)) return undefined; // busqué, leyó: must be given
        if (v.stem.length < 2) return undefined; // ver: vi, vio (no accents); ir, dar: irregular
        if (v.cls === "ir" && v.present && v.present[0] !== `${v.reflexive ? "me " : ""}${v.stem}o`) return undefined; // pedir → pidió, dormir → durmió
        x = v.stem + ES_PRETERITE_END[v.cls][i];
        if (v.reflexive) x = `${ES_REFL[i]} ${x}`;
        rule = `Regular -${v.cls} preterite: stem ${v.stem}- + -${ES_PRETERITE_END[v.cls][i]}`;
      }
      return { answers: withPronouns(x, ES_PRONOUNS[i], "es"), rule };
    }
    case "perfect": {
      const { p, given } = esParticiple(v);
      const x = `${v.reflexive ? ES_REFL[i] + " " : ""}${HABER[i]} ${p}`;
      const rule = `Pretérito perfecto: haber (${HABER[i]}) + the participle ${p}${given ? " (irregular)" : v.cls === "ar" ? " (-ar → -ado)" : " (-er/-ir → -ido)"}`;
      return { answers: withPronouns(x, ES_PRONOUNS[i], "es"), rule };
    }
    case "imperfect": {
      const given = table(v.f.imperfect);
      let x: string;
      if (given) x = given[i];
      else {
        if (["ser", "ir", "ver"].includes(v.base)) return undefined; // era, iba, veía: must be given
        x = v.stem + (v.cls === "ar" ? ES_IMPERFECT_AR : ES_IMPERFECT_ER)[i];
      }
      if (v.reflexive && !given) x = `${ES_REFL[i]} ${x}`;
      const rule = given
        ? `${v.term} is irregular in the imperfect: ${given.filter((_, k) => k !== 4).join(", ")}`
        : `Imperfect: stem ${v.stem}- + ${v.cls === "ar" ? "-aba, -abas, -aba, -ábamos, -aban" : "-ía, -ías, -ía, -íamos, -ían"}`;
      return { answers: withPronouns(x, ES_PRONOUNS[i], "es"), rule };
    }
    case "future":
    case "conditional": {
      const stem = esFutureStem(v);
      if (!stem) return undefined;
      const ends = form === "future" ? ES_FUTURE_END : ES_CONDITIONAL_END;
      const x = `${v.reflexive ? ES_REFL[i] + " " : ""}${stem}${ends[i]}`;
      const name = form === "future" ? "Future" : "Conditional";
      const rule = v.f.futureStem
        ? `${name}: the irregular stem ${stem}- + -${ends[i]}`
        : `${name}: the whole infinitive (${stem}) + -${ends[i]}`;
      return { answers: withPronouns(x, ES_PRONOUNS[i], "es"), rule };
    }
    case "gerund": {
      if (v.reflexive) return undefined;
      if (v.f.gerund) return { answers: alts(v.f.gerund), rule: `${v.term} has an irregular gerund: ${v.f.gerund}` };
      if (v.base === "ir") return { answers: ["yendo"], rule: "ir: the gerund is yendo" };
      if (["poder", "reír", "sonreír", "freír"].includes(v.base)) return undefined;
      if (/[^g]uir$/.test(v.base)) return { answers: [v.stem + "yendo"], rule: `-uir verbs: -iendo is spelled -yendo (${v.stem}yendo)` };
      if (v.cls === "ir" && v.present && alts(v.present[0])[0] !== `${v.stem}o`) return undefined; // pedir → pidiendo: must be given
      if (v.cls !== "ar" && /[aeiou]$/.test(v.stem.replace(/[áéíóú]$/, (c) => "aeiou"["áéíóú".indexOf(c)])))
        return { answers: [v.stem.replace(/í$/, "i") + "yendo"], rule: `After a vowel, -iendo is spelled -yendo: ${v.stem}yendo` };
      const x = v.stem + (v.cls === "ar" ? "ando" : "iendo");
      return { answers: [x], rule: `Gerund: stem ${v.stem}- + ${v.cls === "ar" ? "-ando" : "-iendo"} (estar + gerund: estoy ${x})` };
    }
    case "imperative": {
      if (person === "tú") {
        if (v.f.imperative) return { answers: [v.f.imperative], rule: `tú command of ${v.term}: ${v.f.imperative}` };
        if (v.reflexive) return undefined; // levántate: the accent must be given
        const x = esPresent(v, 2).form;
        return { answers: alts(x), rule: `Affirmative tú command: the él/ella form of the present (${x})` };
      }
      if (person === "usted") {
        if (v.f.imperativeUsted) return { answers: [v.f.imperativeUsted], rule: `usted command of ${v.term}: ${v.f.imperativeUsted}` };
        if (v.reflexive) return undefined;
        const yo = alts(esPresent(v, 0).form)[0];
        if (!yo.endsWith("o")) return undefined; // soy, voy, doy, sé, estoy: must be given
        let root = yo.slice(0, -1);
        let end = v.cls === "ar" ? "e" : "a";
        if (v.cls === "ar" && /c$/.test(root)) root = root.slice(0, -1) + "qu";
        else if (v.cls === "ar" && /g$/.test(root)) root = root + "u";
        else if (v.cls === "ar" && /z$/.test(root)) root = root.slice(0, -1) + "c";
        const x = root + end;
        return { answers: [x], rule: `usted command: the yo form (${yo}) without -o, + -${end}${v.cls === "ar" ? " (-ar verbs take -e)" : " (-er/-ir verbs take -a)"}` };
      }
      return undefined;
    }
  }
  return undefined;
}

export function esWordWarnings(item: VocabItem): string[] {
  const out: string[] = [];
  const term = item.term.trim().replace(/se$/, "");
  const f = item.forms ?? {};
  if (ES_IRREGULAR.includes(term) && !f.present && !f.preterite)
    out.push(`"${item.term}" is usually irregular (stem change or irregular yo): check whether it needs forms.present or forms.preterite`);
  if (/[iu]ar$/.test(term) && !f.present) out.push(`"${item.term}": some -iar/-uar verbs stress the i or u (envío, continúo), others don't (estudio): check whether it needs forms.present`);
  if (ES_IRREGULAR_FUTURE.test(term) && !f.futureStem) out.push(`"${item.term}" has an irregular future stem (tendr-, har-, dir-…): give forms.futureStem or the future and conditional aren't drilled`);
  if (/ir$/.test(term) && term !== "ir" && !/se$/.test(item.term.trim()) && f.present && !f.gerund && !/(salir|vivir|escribir|abrir|subir|recibir|decidir|cubrir|existir|permitir|insistir|asistir|unir|partir|compartir|discutir|sufrir|imprimir|interrumpir|describir|añadir|ocurrir)$/.test(term))
    out.push(`"${item.term}" has an irregular present: if its gerund changes too (pidiendo, durmiendo, diciendo, viniendo), give forms.gerund; otherwise it isn't drilled`);
  if (/(car|gar|zar)$/.test(term) && !f.preterite) out.push(`"${item.term}" respells its yo preterite (busqué, llegué, empecé): give forms.preterite or the preterite isn't drilled`);
  if (/(ar|er|ir)se$/.test(item.term) && !f.imperative) out.push(`reflexive "${item.term}" has no forms.imperative/imperativeUsted (levántate, levántese): its commands aren't drilled`);
  if (["abrir", "escribir", "ver", "volver", "poner", "hacer", "decir", "romper", "morir", "descubrir", "devolver", "resolver", "cubrir", "satisfacer", "freír", "imprimir"].includes(term) && !f.participle)
    out.push(`"${item.term}" has an irregular participle: give forms.participle`);
  return out;
}

// ---------------------------------------------------------------------------------------------
// French

interface FrVerb {
  term: string;
  cls: "er" | "ir" | "re" | "irr";
  reflexive: boolean;
  base: string;
  stem: string;
  present?: string[];
  f: NonNullable<VocabItem["forms"]>;
  etre: boolean;
}

const FR_REFL = ["me", "te", "se", "nous", "vous", "se"];
const FR_END = { er: ["e", "es", "e", "ons", "ez", "ent"], ir: ["is", "is", "it", "issons", "issez", "issent"], re: ["s", "s", "", "ons", "ez", "ent"] };
const AVOIR = ["ai", "as", "a", "avons", "avez", "ont"];
const ETRE = ["suis", "es", "est", "sommes", "êtes", "sont"];
const VOWEL_START = /^[aeiouyhâàéèêëîïôûœ]/i;
const FR_ETRE_VERBS = [
  "aller", "venir", "partir", "arriver", "entrer", "sortir", "rester", "tomber", "naître", "mourir", "monter", "descendre", "retourner",
  "devenir", "revenir", "rentrer", "passer",
];

/** A reflexive pronoun before a verb form: me → m' before a vowel or h. */
const refl = (pron: string, form: string) => (["me", "te", "se"].includes(pron) && VOWEL_START.test(form) ? `${pron[0]}'${form}` : `${pron} ${form}`);

function frVerb(item: VocabItem): FrVerb | string {
  const term = item.term.trim().replace(/’/g, "'");
  const cls = item.conj as FrVerb["cls"];
  if (!["er", "ir", "re", "irr"].includes(cls)) return `"${item.conj}" isn't a French verb class (er, ir, re, irr)`;
  const m = /^(?:(se |s')?)([a-zàâçéèêëîïôûùœ]+)$/.exec(term);
  if (!m) return `"${term}" must be a one-word infinitive in lower case (se lever, s'appeler for pronominal verbs)`;
  const reflexive = !!m[1];
  const base = m[2];
  const f = item.forms ?? {};
  if (f.preterite || f.imperativeUsted || f.imperfect || f.gerund) return `forms.preterite, imperfect, gerund and imperativeUsted are for Spanish`;
  if (f.present && !table(f.present)) return `forms.present needs six comma-separated forms (je, tu, il, nous, vous, ils)`;
  const present = table(f.present);
  if (present && reflexive && !present.every((x, i) => x.startsWith(FR_REFL[i] + " ") || x.startsWith(FR_REFL[i][0] + "'")))
    return `forms.present of a pronominal verb gives the pronouns: "me lève, te lèves, se lève, nous levons, vous levez, se lèvent"`;
  if (f.aux && f.aux !== "être") return `forms.aux is "être" or left out (avoir)`;
  if (f.imperative && f.imperative.split(",").map((x) => x.trim()).filter(Boolean).length !== 3) return `forms.imperative needs three forms: tu, nous, vous`;
  if (cls === "irr") {
    const need = [!present && "forms.present", !f.participle && "forms.participle"].filter(Boolean);
    if (need.length) return `irregular (irr) verbs need ${need.join(" and ")}`;
  } else {
    const ending = cls === "re" ? "re" : base.slice(-2);
    if (!base.endsWith(cls)) return `"${term}" doesn't end in -${cls}${ending ? "" : ""}`;
    if (cls === "er" && base === "aller") return `aller is irregular: use conj irr`;
    if (cls === "er" && !present && (/(ger|cer|yer)$/.test(base) || /[eé]([bcdfghjklmnpqrstvwxz]|ch)er$/.test(base)))
      return `"${term}" changes its spelling in the present (mangeons, commençons, achète, préfère, paie, appelle): give forms.present`;
  }
  const stem = cls === "irr" ? "" : base.slice(0, -2);
  const etre = reflexive || f.aux === "être";
  return { term, cls, reflexive, base, stem, present, f, etre };
}

const FR_IMPERFECT_END = ["ais", "ais", "ait", "ions", "iez", "aient"];
const FR_FUTURE_END = ["ai", "as", "a", "ons", "ez", "ont"];
/** Verbs (and compounds) whose future stem isn't made from the infinitive: ser-, aur-, ir-, fer-, viendr-… */
const FR_IRREGULAR_FUTURE = /^(être|avoir|aller|faire|défaire|refaire|satisfaire|.*venir|.*tenir|envoyer|renvoyer|courir|parcourir|mourir|cueillir|accueillir|recueillir|acquérir|conquérir|falloir|.*oir)$/;

function frFutureStems(v: FrVerb): string[] {
  if (v.f.futureStem) return alts(v.f.futureStem);
  if (FR_IRREGULAR_FUTURE.test(v.base)) return [];
  if (v.cls === "re" || (v.cls === "irr" && v.base.endsWith("re"))) return [v.base.slice(0, -1)];
  if (v.cls === "er" && v.present) {
    const je = alts(v.present[0]).map((x) => x.replace(/^(me |m')/, ""));
    const out = je.map((x) => x + "r");
    // é → è verbs (préférer: je préfère) keep é in the traditional future (préférerai); 1990 spelling préfèrerai.
    if (je.some((x) => x.replace(/è(?=[^è]*$)/, "é") + "r" === v.base)) out.unshift(v.base);
    return [...new Set(out)];
  }
  return [v.base];
}

export function frWordProblem(item: VocabItem): string | undefined {
  const v = frVerb(item);
  return typeof v === "string" ? v : undefined;
}

function frPresent(v: FrVerb, i: number): { form: string; given: boolean } {
  if (v.present) return { form: v.present[i], given: true };
  const x = v.stem + FR_END[v.cls as "er"][i];
  return { form: v.reflexive ? refl(FR_REFL[i], x) : x, given: false };
}

function frParticiple(v: FrVerb): { p: string; given: boolean } {
  if (v.f.participle) return { p: v.f.participle, given: true };
  return { p: v.stem + { er: "é", ir: "i", re: "u", irr: "" }[v.cls], given: false };
}

/** French answers: the verb alone or with a subject pronoun (j' before a vowel). */
function frAnswers(forms: string[], i: number): string[] {
  return [...new Set(forms.flatMap((x) => withPronouns(x, FR_PRONOUNS[i], "fr")))];
}

export function frVerbForm(item: VocabItem, form: string, person: string | number): RomanceGenerated | undefined {
  const v = frVerb(item);
  if (typeof v === "string") return undefined;
  switch (form) {
    case "present": {
      const i = Number(person);
      const { form: x, given } = frPresent(v, i);
      const rule = given
        ? `${v.term} is irregular in the present: ${v.present!.map((y, k) => `${FR_LABEL[k].split("/")[0]} ${y}`).join(", ")}`
        : `Regular -${v.cls} verb: stem ${v.stem}- + -${FR_END[v.cls as "er"][i] || "(no ending)"}${v.reflexive ? `, with the pronoun ${FR_REFL[i]}` : ""}`;
      return { answers: frAnswers([x], i), rule };
    }
    case "perfect": {
      const i = Number(person);
      const { p, given } = frParticiple(v);
      const aux = (v.etre ? ETRE : AVOIR)[i];
      // With être the participle agrees with the subject: accept every agreement the person allows.
      const parts = !v.etre ? [p] : i === 2 ? [p, p + "e"] : i < 2 ? [p, p + "e"] : i === 4 ? [p, p + "e", p + "s", p + "es"] : [p + "s", p + "es"];
      const forms = parts.map((pp) => (v.reflexive ? `${refl(FR_REFL[i], aux)} ${pp}` : `${aux} ${pp}`));
      const verb = (pp: string) => (v.reflexive ? `${refl(FR_REFL[i], aux)} ${pp}` : `${aux} ${pp}`);
      // With être and a subject that shows gender, the agreement must match it: il est allé, elle est allée.
      const gendered: string[] | undefined = !v.etre
        ? undefined
        : i === 2
          ? [verb(p), verb(p + "e"), `il ${verb(p)}`, `Il ${verb(p)}`, `elle ${verb(p + "e")}`, `Elle ${verb(p + "e")}`, ...[p, p + "e", p + "s", p + "es"].flatMap((x) => [`on ${verb(x)}`, `On ${verb(x)}`])]
          : i === 5
            ? [verb(p + "s"), verb(p + "es"), `ils ${verb(p + "s")}`, `Ils ${verb(p + "s")}`, `elles ${verb(p + "es")}`, `Elles ${verb(p + "es")}`]
            : undefined;
      const how = given ? "" : ` (-${v.cls} → -${{ er: "é", ir: "i", re: "u", irr: "" }[v.cls]})`;
      const rule = v.etre
        ? `Passé composé with être (${aux}) + ${p}${how}; the participle agrees with the subject (${p}, ${p}e, ${p}s, ${p}es)${v.reflexive ? "; pronominal verbs always take être" : ""}`
        : `Passé composé: avoir (${aux}) + the participle ${p}${how}`;
      return { answers: gendered ?? frAnswers(forms, i), rule };
    }
    case "imperfect": {
      const i = Number(person);
      let stem: string | undefined = v.f.imperfectStem;
      if (!stem) {
        if (v.base === "être") return undefined; // ét-: must be given
        const nous = (v.present ? alts(v.present[3])[0] : v.stem + FR_END[v.cls as "er"][3]).replace(/^nous /, "");
        if (!nous.endsWith("ons")) return undefined;
        stem = nous.slice(0, -3);
      }
      let st = stem;
      if (i === 3 || i === 4) st = st.replace(/ge$/, "g").replace(/ç$/, "c"); // mangions, commencions
      const x0 = st + FR_IMPERFECT_END[i];
      const x = v.reflexive ? refl(FR_REFL[i], x0) : x0;
      const rule = v.f.imperfectStem
        ? `Imparfait: the stem ${stem}- + -ais, -ais, -ait, -ions, -iez, -aient`
        : `Imparfait: the nous present without -ons (${stem}-) + -${FR_IMPERFECT_END[i]}`;
      return { answers: frAnswers([x], i), rule };
    }
    case "future":
    case "conditional": {
      const i = Number(person);
      const stems = frFutureStems(v);
      if (!stems.length) return undefined;
      const ends = form === "future" ? FR_FUTURE_END : FR_IMPERFECT_END;
      const xs = stems.map((st) => (v.reflexive ? refl(FR_REFL[i], st + ends[i]) : st + ends[i]));
      const name = form === "future" ? "Futur simple" : "Conditionnel";
      const rule = v.f.futureStem
        ? `${name}: the irregular stem ${stems[0]}- + -${ends[i]}`
        : `${name}: ${v.cls === "re" || (v.cls === "irr" && v.base.endsWith("re")) ? "the infinitive without its final -e" : v.present && v.cls === "er" ? "the je present + r" : "the infinitive"} (${stems[0]}-) + -${ends[i]}`;
      return { answers: frAnswers(xs, i), rule };
    }
    case "imperative": {
      const k = FR_IMPERATIVES.indexOf(person as never);
      if (k < 0) return undefined;
      const given = v.f.imperative?.split(",").map((x) => x.trim());
      let x: string;
      if (given) x = given[k];
      else {
        const presentIndex = [1, 3, 4][k];
        const cell = v.present ? v.present[presentIndex] : v.stem + FR_END[v.cls as "er"][presentIndex];
        const forms: string[] = [];
        for (let p of alts(cell)) {
          if (v.reflexive) p = p.replace(/^(te|nous|vous) /, "").replace(/^t'/, "");
          if (k === 0 && /es$/.test(p) && (v.cls === "er" || v.cls === "irr")) p = p.slice(0, -1); // parles → parle; ouvres → ouvre
          if (k === 0 && v.cls === "irr" && p === "vas") return undefined;
          forms.push(v.reflexive ? `${p}-${["toi", "nous", "vous"][k]}` : p);
        }
        x = forms.join("/");
      }
      const rule = given
        ? `Imperative of ${v.term}: ${given.join(", ")}`
        : `Imperative: the ${["tu", "nous", "vous"][k]} present without the pronoun${k === 0 && v.cls === "er" ? "; -er verbs drop the -s for tu" : ""}${v.reflexive ? `, with -${["toi", "nous", "vous"][k]} after it` : ""}`;
      return { answers: [...new Set(alts(x).flatMap((y) => [y, y.replace(/-/g, " ")]))], rule };
    }
  }
  return undefined;
}

export function frWordWarnings(item: VocabItem): string[] {
  const out: string[] = [];
  const f = item.forms ?? {};
  const base = item.term.trim().replace(/^(se |s')/, "");
  if (FR_ETRE_VERBS.includes(base) && f.aux !== "être" && base !== "passer") out.push(`"${item.term}" takes être in the passé composé: add forms.aux "être"`);
  if (FR_IRREGULAR_FUTURE.test(base) && !f.futureStem) out.push(`"${item.term}" has an irregular future stem (ser-, aur-, ir-, fer-, viendr-…): give forms.futureStem or the future and conditional aren't drilled`);
  if (item.conj === "irr" && ["être", "avoir", "savoir", "vouloir"].includes(base) && !f.imperative) out.push(`"${item.term}" has an irregular imperative: give forms.imperative (tu, nous, vous)`);
  if (item.conj === "er" && /[eé](bl|br|cl|cr|dr|gl|gr|pl|pr|tr|vr)er$/.test(base) && !f.present) out.push(`"${item.term}" may change e → è (célèbre): check whether it needs forms.present`);
  if (item.conj === "ir" && ["partir", "sortir", "dormir", "sentir", "servir", "mentir", "ouvrir", "offrir", "souffrir", "venir", "tenir", "courir", "mourir", "cueillir", "fuir"].includes(base))
    out.push(`"${item.term}" isn't a finir-type verb: use conj irr with forms.present and forms.participle`);
  return out;
}
